function parseCutDecision(cut){
  try{
    const raw=String(cut.notes||'');
    const meta=raw.startsWith('LMOS_CUT:')?JSON.parse(raw.slice(9)):{};
    const rolls=Number(cut.bales||cut.rolls||0),weight=Number(meta.weight||500),sold=Number(meta.sold_rolls||0);
    const costs=['fuel_cost','tractor_cost','mower_cost','rake_cost','baler_cost','labor_cost','machinery_cost','freight_cost','repairs_cost','other_cost'].reduce((sum,k)=>sum+Number(meta[k]||0),0);
    const revenue=sold*Number(meta.sale_price_per_roll||0)+(Number(meta.sale_price_per_ton||0)>0?Math.max(0,(rolls-sold)*weight/1000)*Number(meta.sale_price_per_ton||0):0);
    return {...cut,meta,rolls,weight,sold,stock:Math.max(0,rolls-sold),tons:rolls*weight/1000,costs,revenue,margin:revenue-costs};
  }catch(_e){return {...cut,meta:{},rolls:Number(cut.bales||cut.rolls||0),weight:500,sold:0,stock:Number(cut.bales||cut.rolls||0),tons:Number(cut.total_kg||0)/1000,costs:0,revenue:0,margin:0}}
}
function alfalfaDecisionPage(){
  const cuts=S.cuts.map(parseCutDecision).sort((a,b)=>String(b.cut_date||'').localeCompare(String(a.cut_date||'')));
  const alfalfaLots=S.lots.filter(l=>String(l.crop||'').toLowerCase().includes('alfalfa'));
  const totalRolls=cuts.reduce((n,c)=>n+c.rolls,0),stock=cuts.reduce((n,c)=>n+c.stock,0),tons=cuts.reduce((n,c)=>n+c.tons,0);
  const costs=cuts.reduce((n,c)=>n+c.costs,0),revenue=cuts.reduce((n,c)=>n+c.revenue,0),margin=revenue-costs;
  const today=Date.now();
  const plans=alfalfaLots.map(l=>{
    const lotCuts=cuts.filter(c=>c.lot_id===l.id);
    const last=lotCuts[0];
    const days=last?.cut_date?Math.max(0,Math.floor((today-new Date(last.cut_date+'T12:00:00').getTime())/86400000)):999;
    const due=days>=32?'Cortar ahora':days>=26?'Preparar corte':days>=20?'Monitorear':'En crecimiento';
    const score=days>=32?4:days>=26?3:days>=20?2:1;
    const nd=latest(l);
    return {l,last,days,due,score,ndvi:Number(nd?.ndvi_avg||0)};
  }).sort((a,b)=>b.score-a.score||b.days-a.days);
  const alerts=[];
  plans.filter(x=>x.days>=32).forEach(x=>alerts.push(`${x.l.name}: ${x.days} días desde el último corte.`));
  cuts.filter(c=>Number(c.meta.humidity||0)>20).slice(0,4).forEach(c=>alerts.push(`${S.lots.find(l=>l.id===c.lot_id)?.name||'Lote'}: humedad ${number(c.meta.humidity,1)}%, revisar almacenamiento.`));
  cuts.filter(c=>c.margin<0&&c.revenue>0).slice(0,4).forEach(c=>alerts.push(`${S.lots.find(l=>l.id===c.lot_id)?.name||'Lote'}: margen negativo en el corte del ${shortDate(c.cut_date)}.`));
  const planRows=plans.map(x=>`<tr><td><b>${esc(x.l.name)}</b><small>${hectares(x.l.hectares||x.l.area_ha)}</small></td><td>${x.last?shortDate(x.last.cut_date):'Sin registrar'}</td><td>${x.last?`${x.days} días`:'—'}</td><td>${x.ndvi?number(x.ndvi,2):'—'}</td><td><span class="pill ${x.score>=4?'bad':x.score>=3?'warn':''}">${x.due}</span></td><td><button class="secondary goProduction">Abrir producción</button></td></tr>`).join('');
  const recent=cuts.slice(0,8).map(c=>`<tr><td>${shortDate(c.cut_date)}</td><td><b>${esc(S.lots.find(l=>l.id===c.lot_id)?.name||'Lote')}</b></td><td>${number(c.rolls)} rollos<small>${number(c.tons,1)} t</small></td><td>${number(c.stock)} rollos</td><td>${money(c.costs)}</td><td class="${c.margin>=0?'positive':'negative'}">${money(c.margin)}</td></tr>`).join('');
  return `<div class="page-head"><div><p class="eyebrow">GESTIÓN DE ALFALFA 5.0</p><h2>Alfalfa: producción, stock y próximos cortes</h2><p class="muted">Prioridades automáticas construidas con los datos ya registrados en cada lote y corte.</p></div><button class="primary newCut">+ Registrar corte</button></div>
  <div class="metrics"><div class="metric"><span>Producción acumulada</span><b>${number(totalRolls)} rollos</b><small>${number(tons,1)} toneladas</small></div><div class="metric"><span>Stock estimado</span><b>${number(stock)} rollos</b><small>producidos menos vendidos</small></div><div class="metric"><span>Costo acumulado</span><b>${money(costs)}</b><small>${totalRolls?money(costs/totalRolls):money(0)} por rollo</small></div><div class="metric"><span>Margen registrado</span><b>${money(margin)}</b><small>Ingresos ${money(revenue)}</small></div></div>
  <div class="grid2"><div class="panel"><div class="panel-title"><div><h3>Planificador de cortes</h3><p class="muted">Ventana orientativa: preparar desde 26 días y priorizar desde 32 días.</p></div></div><div class="table-wrap"><table class="table"><thead><tr><th>Lote</th><th>Último corte</th><th>Días</th><th>NDVI</th><th>Decisión</th><th></th></tr></thead><tbody>${planRows||'<tr><td colspan="6" class="empty">No hay lotes de alfalfa.</td></tr>'}</tbody></table></div></div><div class="panel"><h3>Alertas de gestión</h3>${alerts.length?alerts.slice(0,10).map(a=>`<div class="row"><div><b>⚠ ${esc(a)}</b></div></div>`).join(''):'<div class="status">No hay alertas automáticas con los datos actuales.</div>'}<div class="status" style="margin-top:14px"><b>Recomendación LM AI</b><br>${plans[0]?`${esc(plans[0].l.name)} es la prioridad actual: ${esc(plans[0].due.toLowerCase())}. Confirmar estado del cultivo, humedad y pronóstico antes de operar.`:'Cargá cortes para generar prioridades automáticas.'}</div></div></div>
  <div class="panel" style="margin-top:18px"><div class="panel-title"><div><h3>Resultado por corte</h3><p class="muted">Producción, stock y margen según los datos cargados.</p></div><button class="secondary goProduction">Ver módulo completo</button></div><div class="table-wrap"><table class="table"><thead><tr><th>Fecha</th><th>Lote</th><th>Producción</th><th>Stock</th><th>Costos</th><th>Margen</th></tr></thead><tbody>${recent||'<tr><td colspan="6" class="empty">Todavía no hay cortes registrados.</td></tr>'}</tbody></table></div></div>`;
}
function flightsPage(){
  const analyses=[...S.analyses].sort((a,b)=>String(b.flight_date||'').localeCompare(String(a.flight_date||'')));
  const analysedLots=new Set(analyses.map(a=>a.lot_id)).size;
  const average=analyses.length?analyses.reduce((sum,a)=>sum+Number(a.ndvi_avg||0),0)/analyses.length:0;
  const lowVigor=analyses.filter(a=>Number(a.low_vigor_pct||0)>15).length;
  const cards=analyses.map(a=>{
    const lot=S.lots.find(l=>l.id===a.lot_id);
    const history=analyses.filter(x=>x.lot_id===a.lot_id);
    const position=history.findIndex(x=>x.id===a.id);
    const prior=position>=0?history[position+1]:null;
    const delta=prior?Number(a.ndvi_avg||0)-Number(prior.ndvi_avg||0):null;
    const v=vigor(a.ndvi_avg);
    return `<article class="analysis-card"><div class="panel-title"><div><b>${esc(lot?.name||'Lote sin identificar')}</b><small class="muted">${shortDate(a.flight_date)} · ${hectares(a.hectares||lot?.hectares||0)}</small></div><span class="pill ${v[1]}">${v[0]}</span></div><span>NDVI promedio</span><b class="big">${number(a.ndvi_avg,2)}</b><div class="progress"><i style="width:${Math.max(0,Math.min(100,Number(a.ndvi_avg||0)*100))}%"></i></div><p>NDRE ${number(a.ndre_avg,2)} · Bajo vigor ${number(a.low_vigor_pct,1)}%</p><p class="muted">${delta==null?'Primer análisis del lote':`Cambio vs. vuelo anterior: ${delta>=0?'+':''}${number(delta,2)}`}</p><p>${esc(a.recommendation||'Sin recomendación registrada.')}</p><div class="actions"><button class="secondary makeOrder" data-id="${a.id}">Crear orden T100</button><button class="secondary openFile" data-path="${esc(a.map_file_path||'')}">Abrir mapa</button></div></article>`;
  }).join('');
  return `<div class="page-head"><div><p class="eyebrow">DJI MAVIC 3 MULTISPECTRAL</p><h2>Vuelos y análisis</h2><p class="muted">Historial multiespectral, vigor por lote y generación de órdenes de aplicación.</p></div><button class="primary newAnalysis">+ Importar análisis</button></div><div class="metrics"><div class="metric"><span>Vuelos procesados</span><b>${number(analyses.length)}</b><small>análisis guardados</small></div><div class="metric"><span>Lotes analizados</span><b>${number(analysedLots)}</b><small>de ${number(S.lots.length)} lotes</small></div><div class="metric"><span>NDVI promedio</span><b>${analyses.length?number(average,2):'—'}</b><small>promedio histórico</small></div><div class="metric"><span>Requieren revisión</span><b>${number(lowVigor)}</b><small>más de 15% de bajo vigor</small></div></div><div class="grid3">${cards||'<div class="panel empty"><h3>Todavía no hay vuelos procesados</h3><p>Importá un CSV de zonas para calcular NDVI, NDRE y porcentaje de bajo vigor.</p><button class="primary newAnalysis">Importar primer análisis</button></div>'}</div>`;
}

